// Floor (derived): a joist floor built on site, on a sill all round, derived
// from the walls standing on it (hut/design/ic_derived.md section 11; the
// floor's rules in hut/design/ic_lib_floor.md section 11). Pure: no imports; the engine passes the library core.
//
// derive(params, input, core) -> {parts, joints}
//   params  joist (lumber), spacing, buildup (system file)
//   input   width, depth: the outline (the walls' framing), u along the rims,
//           v along the joists (the short side); sill: the walls' stud lumber
//           (laid flat); gables: {start, end}, for the edges at u = 0 and u =
//           width, the walls' members standing over them as [v0, v1]
//           intervals; toWorld(box): floor coordinates to the world's
//   result  parts in world coordinates, joints between own parts
//
// Floor coordinates: origin at the outline's corner, at the underside of the
// sill; u along the rims, v along the joists, z up. Sills: the start and end
// rows (v) the full width, the gable rows between. Rims along u at both ends
// of the joists; joists along v: an end joist at each gable edge and joists
// at the spacing from the u = 0 edge, left out within MIN_BAY of an end
// joist. Blocking between each end joist and the next joist, one block under
// each member over the gable edge; members side by side (a panel joint, a
// king and jack) get blocks side by side, centred under them. Members over a
// rim joist (the end studs of a gable wall that runs through at a corner)
// stand on the rim and need no block. Sheet layers on
// face B on top, laid in rows across the joists, every other row starting with
// a half sheet; a seam across the joists must land on a joist.

const MIN_BEARING = 20; // mm of joist under each sheet at a seam
const MIN_SHEET = 100; // mm; a narrower last row or end piece is an error
const MIN_BAY = 100; // mm; a grid joist closer than this to an end joist is left out

/** @typedef {{min: number[], max: number[]}} Box */

/**
 * Blocks under members: members side by side are grouped, and a group of
 * n gets n blocks side by side, t thick, centred under it.
 * @param {number[][]} members  [v0, v1], sorted
 * @param {number} t
 */
function blockSpans(members, t) {
  /** @type {number[][]} */
  const groups = [];
  for (const [v0, v1] of members) {
    const last = groups[groups.length - 1];
    if (last && last[1] === v0) { last[1] = v1; last[2] += 1; } else groups.push([v0, v1, 1]);
  }
  /** @type {number[][]} */
  const spans = [];
  for (const [v0, v1, n] of groups) {
    const lo = (v0 + v1) / 2 - (n * t) / 2;
    if (spans.length && lo < spans[spans.length - 1][1]) {
      throw new Error(`the blocks under the members at v ${v0} would overlap the blocks before them`);
    }
    for (let i = 0; i < n; i++) spans.push([lo + i * t, lo + (i + 1) * t]);
  }
  return spans;
}

/**
 * @param {any} params
 * @param {any} input
 * @param {any} core
 */
export function derive(params, input, core) {
  const { width, depth, sill: wall, gables, toWorld } = input;
  const { spacing, buildup } = params;
  const [t, d] = params.joist.section; // 48 x 198: thickness along u, depth up
  const [st, sw] = wall.section; // the sill: the walls' stud lumber lying flat
  for (const layer of buildup.face_b) {
    if (!layer.sheet) throw new Error(`floor layer '${layer.role}' on face_b must be a catalog sheet`);
  }
  if (width < 2 * sw || depth < 2 * sw) {
    throw new Error(`the floor (${width} x ${depth}) is too small for its sills (${sw} wide)`);
  }
  if (t < 2 * MIN_BEARING) throw new Error(`joists ${t} thick leave less than ${MIN_BEARING} for each sheet at a seam`);

  /** @type {any[]} */
  const parts = [];
  /** @type {any[]} */
  const joints = [];
  const box = (/** @type {number[]} */ ...c) => ({ min: [c[0], c[1], c[2]], max: [c[3], c[4], c[5]] });
  const member = (/** @type {string} */ id, /** @type {string} */ role, /** @type {Box} */ b, lumber = params.joist) => {
    const part = { id, role, material: `timber ${lumber.grade}`, catalog: lumber.id, stage: 'site', box: b };
    parts.push(part);
    return part;
  };
  const joint = (/** @type {string} */ type, /** @type {Object<string, string>} */ sides) => joints.push({
    type, parts: Object.fromEntries(Object.entries(sides).map(([side, id]) => [side, { own: id }])),
  });

  let z0 = st, z1 = st + d; // the framing on the sill
  const sills = [
    member('sill_start', 'sill_plate', box(0, 0, 0, width, sw, st), wall),
    member('sill_end', 'sill_plate', box(0, depth - sw, 0, width, depth, st), wall),
    member('sill_gable_start', 'sill_plate', box(0, sw, 0, sw, depth - sw, st), wall),
    member('sill_gable_end', 'sill_plate', box(width - sw, sw, 0, width, depth - sw, st), wall),
  ];
  for (const a of sills.slice(0, 2)) for (const b of sills.slice(2)) joint('sill_corner', { a: a.id, b: b.id });

  const rims = [
    member('rim_start', 'rim', box(0, 0, z0, width, t, z1)),
    member('rim_end', 'rim', box(0, depth - t, z0, width, depth, z1)),
  ];
  /** @type {Array<[string, number]>} */
  const positions = [['joist_start', 0]];
  for (let k = 1; k * spacing < width; k++) {
    const u0 = k * spacing - t / 2;
    if (u0 >= t + MIN_BAY && u0 + t <= width - t - MIN_BAY) positions.push([`joist_${k}`, u0]);
  }
  positions.push(['joist_end', width - t]);
  if (positions.length < 3) throw new Error(`width ${width}: no joist between the end joists for the blocking`);
  const joists = positions.map(([id, u0]) => {
    const j = member(id, 'joist', box(u0, t, z0, u0 + t, depth - t, z1));
    for (const rim of rims) joint('joist_to_rim', { rim: rim.id, joist: id });
    return j;
  });

  /** @type {any[]} */
  const blocks = [];
  const sides = [['gable_start', joists[0], joists[1], gables.start], ['gable_end', joists[joists.length - 2], joists[joists.length - 1], gables.end]];
  for (const [side, a, b, members] of sides) {
    const u0 = a.box.max[0], u1 = b.box.min[0];
    const between = members.filter((/** @type {number[]} */ [v0, v1]) => v1 > t && v0 < depth - t);
    const spans = between.length ? blockSpans([...between].sort((p, q) => p[0] - q[0]), t) : [];
    if (spans.length && (spans[0][0] < t || spans[spans.length - 1][1] > depth - t)) {
      throw new Error(`the ${side} blocking would run into a rim joist`);
    }
    /** @type {any} */
    let previous = null;
    spans.forEach(([v0, v1], i) => {
      const block = member(`blocking_${side}_${i + 1}`, 'blocking', box(u0, v0, z0, u1, v1, z1));
      blocks.push(block);
      for (const j of [a, b]) joint('blocking_to_joist', { joist: j.id, block: block.id });
      if (previous && previous.box.max[1] === v0) joint('doubled_blocking', { a: previous.id, b: block.id });
      previous = block;
    });
  }

  // Everything resting on the sill is toenailed to it (a count, so however
  // little it rests there).
  const members = [...rims, ...joists, ...blocks];
  for (const m of members) {
    for (const s of sills) if (core.faceToFace(m.box, s.box, 2)) joint('on_sill', { sill: s.id, member: m.id });
  }

  let z = z1;
  buildup.face_b.forEach((/** @type {any} */ layer, /** @type {number} */ index) => {
    const sheet = layer.sheet;
    z0 = z; z1 = z + layer.thickness; z = z1;
    const longSide = Math.max(...sheet.size), shortSide = Math.min(...sheet.size);
    let n = 0;
    for (let row = 0, v0 = 0; v0 < depth; row++, v0 += shortSide) {
      const v1 = Math.min(v0 + shortSide, depth);
      if (v1 - v0 < MIN_SHEET) {
        throw new Error(`depth ${depth}: the last row of ${layer.role} sheets would be ${v1 - v0} deep (less than ${MIN_SHEET})`);
      }
      const cuts = [0];
      for (let u = row % 2 ? longSide / 2 : longSide; u < width; u += longSide) cuts.push(u);
      cuts.forEach((u0, i) => {
        const u1 = i + 1 < cuts.length ? cuts[i + 1] : width;
        if (u1 - u0 < MIN_SHEET) {
          throw new Error(`width ${width}: a ${layer.role} piece would be ${u1 - u0} wide (less than ${MIN_SHEET})`);
        }
        if (u0 > 0 && !joists.some(j => j.box.min[0] + MIN_BEARING <= u0 && u0 <= j.box.max[0] - MIN_BEARING)) {
          throw new Error(`the ${layer.role} seam at u ${u0} doesn't land on a joist with ${MIN_BEARING} bearing each side`);
        }
        n += 1;
        const part = {
          id: `b${index + 1}_${layer.role}_${n}`, role: layer.role, layer: layer.role, layerDef: layer,
          material: sheet.material, catalog: sheet.id, stage: 'site', box: box(u0, v0, z0, u1, v1, z1),
        };
        parts.push(part);
        for (const m of members) {
          if (core.nailable(part.box, m.box, 2)) joint('sheathing_to_framing', { sheet: part.id, framing: m.id });
        }
      });
    }
  });
  const height = z;
  return {
    parts: parts.map(p => ({ ...p, box: toWorld(p.box, height) })),
    joints,
    height,
  };
}

roof.code:
// Roof (derived): a gable roof of rafters on a ridge board, tied by ceiling
// joists at the plates, with framed gables and a gable overhang
// (hut/design/ic_lib_roof.md, 3 and 4.2). Runs after a storey and reads its
// exports. Pure: no imports; the engine passes the library core.
//
// derive(params, input, core) -> {parts, joints}
//   params  rafter, ceiling_joist, ridge_board, gable_stud, lookout (lumber),
//           spacing (system file); pitch (degrees), ridge (east_west |
//           north_south), eaves, gables (the layout)
//   input   exports of the storey it comes after: outline (the walls'
//           framing in plan), outside (with the sheets), plate_top, lines
//           [{id, side, plates}]; parts: the model so far
//   result  parts in world coordinates (rafters and lookouts sloped: a box in
//           its own frame, with cuts and, for rafters on a wall, a birdsmouth
//           notch; gable studs cut to the slope) and joints
//
// Across the ridge (b), the rafters run from the eaves to the ridge board,
// whose centre is over the middle of the framing. A rafter's birdsmouth has
// its heel at the wall's outer face, sheets included (the seat bears on the
// sheet's top edge and the plate, the tail clears the sheet), and its seat
// on the plates' top, notched a quarter of the rafter's depth, square to it
// (the most the IRC allows at a member's end). A plumb cut meets the ridge
// board; a plumb cut ends the tail `eaves` beyond the outer face. Along the
// ridge (a), an end rafter is flush with each end of the framing, over the
// gable wall, and the others are at the spacing from the start, as the
// studs and the floor joists are.
//
// A ceiling joist lies beside each rafter between the gables, on the plates,
// from one eaves wall's outer framing face to the other's: with the rafters
// it ties their feet. At the gables the gable wall carries the end rafters
// instead: gable studs stand on its upper plate at the spacing across the
// building (not across the ridge line, none shorter than MIN_GABLE_STUD), cut
// at the top to the end rafter's underside.
//
// The gable overhang (gables > 0): the ridge board runs out to `gables`
// beyond the gable walls' outer faces, a fly rafter (no birdsmouth: no wall
// under it) hangs at the edge from it, and lookouts, laid flat with their
// tops flush with the rafters', run from the fly rafter to the end rafter at
// the spacing up the slope (a gable ladder).

const DEG = Math.PI / 180;
const MIN_GABLE_STUD = 150; // mm at its short side; placeholder

/** @typedef {[number, number, number]} V */

/**
 * @param {any} params
 * @param {any} input
 * @param {any} core
 * @returns {{parts: any[], joints: any[]}}
 */
export function derive(params, input, core) {
  const found = Object.entries(input.exports ?? {}).find(([, ex]) => ex && Array.isArray(ex.lines) && ex.outline);
  if (!found) throw new Error('the roof needs a storey before it: list it after one (after: [storey])');
  const [dep, storey] = /** @type {[string, any]} */ (found);
  const a = params.ridge === 'east_west' ? 0 : 1; // along the ridge
  const b = 1 - a; // across it
  const eavesSides = a === 0 ? ['south', 'north'] : ['west', 'east'];
  const gableSides = a === 0 ? ['west', 'east'] : ['south', 'north'];
  const lineOn = (/** @type {string} */ side) => {
    const line = storey.lines.find((/** @type {any} */ l) => l.side === side);
    if (!line) throw new Error(`no ${side} wall`);
    return line;
  };
  for (const side of eavesSides) lineOn(side);
  const [T, D] = params.rafter.section;
  const [tr, dr] = params.ridge_board.section;
  const [tj, dj] = params.ceiling_joist.section;
  const [ts] = params.gable_stud.section;
  const [tl, wl] = params.lookout.section; // laid flat: tl thick, wl wide
  const alpha = params.pitch * DEG, cos = Math.cos(alpha), sin = Math.sin(alpha), tan = Math.tan(alpha);
  const zp = storey.plate_top;
  const lo = storey.outline.min, hi = storey.outline.max, out = storey.outside;
  const ridgeAt = (lo[b] + hi[b]) / 2;
  const heel = D / 4 / cos; // the heel's height: the notch a quarter of the depth, square to the rafter
  if (dr < D / cos) throw new Error(`the ridge board (${dr} deep) is shallower than the rafters' plumb cut (${(D / cos).toFixed(1)})`);
  const overhang = params.gables > 0;

  // Rafter positions along the ridge (centres); fly rafters at the edges.
  const centres = [lo[a] + T / 2];
  for (let k = 1; lo[a] + k * params.spacing <= hi[a] - 1.5 * T; k++) centres.push(lo[a] + k * params.spacing);
  centres.push(hi[a] - T / 2);
  const ridgeEnds = overhang ? [out.min[a] - params.gables, out.max[a] + params.gables] : [lo[a], hi[a]];
  const fly = overhang ? [ridgeEnds[0] + T / 2, ridgeEnds[1] - T / 2] : [];

  const unitAxis = (/** @type {number} */ i, /** @type {number} */ sign = 1) => /** @type {V} */ ([0, 1, 2].map(k => (k === i ? sign : 0)));
  const at = (/** @type {number} */ along, /** @type {number} */ across, /** @type {number} */ z) => {
    /** @type {V} */
    const p = [0, 0, z];
    p[a] = along;
    p[b] = across;
    return p;
  };
  const lumber = (/** @type {any} */ l) => ({ material: `timber ${l.grade}`, catalog: l.id, stage: 'site' });
  /** @type {any[]} */
  const parts = [];
  let ridgeTop = 0;
  /** The underside of the rafters on each side, as a plane: {normal (up, out of the stud), point}. */
  /** @type {Object<string, {normal: V, point: V}>} */
  const undersides = {};
  for (const [side, dir] of /** @type {Array<[string, number]>} */ ([[eavesSides[0], 1], [eavesSides[1], -1]])) {
    const heelAt = dir > 0 ? out.min[b] : out.max[b]; // the wall's outer face, sheets included
    const face = ridgeAt - dir * tr / 2; // the ridge board's face on this side
    const run = (face - heelAt) * dir;
    // The rafters' frame: x their thickness, y up the slope, z square to it, upward.
    const h = unitAxis(b, dir);
    /** @type {V} */
    const ey = [h[0] * cos, h[1] * cos, sin];
    /** @type {V} */
    const ez = [-h[0] * sin, -h[1] * sin, cos];
    /** @type {V} */
    const ex = [ey[1] * ez[2] - ey[2] * ez[1], ey[2] * ez[0] - ey[0] * ez[2], ey[0] * ez[1] - ey[1] * ez[0]];
    ridgeTop = zp - heel + run * tan + D / cos;
    undersides[side] = { normal: ez, point: at(0, heelAt, zp - heel) };
    const frameAt = (/** @type {number} */ along) => {
      const origin = at(along, heelAt, zp - heel); // on the underside, at the heel
      const local = (/** @type {number[]} */ p) => {
        const d = [p[0] - origin[0], p[1] - origin[1], p[2] - origin[2]];
        return [ex, ey, ez].map(e => d[0] * e[0] + d[1] * e[1] + d[2] * e[2]);
      };
      const turn = (/** @type {number[]} */ v) => [ex, ey, ez].map(e => v[0] * e[0] + v[1] * e[1] + v[2] * e[2]);
      return { origin, local, turn };
    };
    const rafter = (/** @type {string} */ id, /** @type {number} */ centre, /** @type {boolean} */ onWall) => {
      const { origin, local, turn } = frameAt(centre);
      const seatCorner = local(at(centre, heelAt, zp));
      parts.push({
        id, role: 'rafter', ...lumber(params.rafter),
        box: { min: [-T / 2, -params.eaves / cos, 0], max: [T / 2, (run + D * sin) / cos, D] },
        frame: { origin, axes: [ex, ey, ez] },
        cuts: [
          { normal: turn(h), point: local(at(centre, face, zp)) }, // the plumb cut at the ridge board
          { normal: turn([-h[0], -h[1], 0]), point: local(at(centre, heelAt - dir * params.eaves, zp)) }, // the tail
        ],
        ...(onWall ? { notches: [{ planes: [ // the birdsmouth: below the seat, inside the heel
          { normal: turn([0, 0, 1]), point: seatCorner },
          { normal: turn([-h[0], -h[1], 0]), point: seatCorner },
        ] }] } : {}),
      });
    };
    centres.forEach((centre, i) => rafter(`rafter_${side}_${i + 1}`, centre, true));
    fly.forEach((centre, i) => rafter(`fly_rafter_${side}_${gableSides[i]}`, centre, false));
    // Lookouts: from each fly rafter's inner face to the end rafter's outer
    // face, flat, tops flush with the rafters', up the slope from the heel,
    // clear of the ridge board.
    if (overhang) {
      const topAt = (run + (D - tl) * sin) / cos - 50; // the plumb cut at the lookout's underside, less 50
      const spans = [[ridgeEnds[0] + T, lo[a]], [hi[a], ridgeEnds[1] - T]];
      spans.forEach(([a0, a1], g) => {
        const { origin, turn } = frameAt(a0);
        const along = turn(unitAxis(a))[0]; // +1 or -1: the frame's x along the ridge
        const xs = along > 0 ? [0, a1 - a0] : [a0 - a1, 0];
        let k = 0;
        for (let s = 0; s + wl <= topAt; s += params.spacing) {
          k += 1;
          parts.push({
            id: `lookout_${side}_${gableSides[g]}_${k}`, role: 'lookout', ...lumber(params.lookout),
            box: { min: [xs[0], s, D - tl], max: [xs[1], s + wl, D] },
            frame: { origin, axes: [ex, ey, ez] },
          });
        }
      });
    }
  }

  const ridgeBoard = {
    id: 'ridge_board', role: 'ridge_board', ...lumber(params.ridge_board),
    box: boxOf(at(ridgeEnds[0], ridgeAt - tr / 2, ridgeTop - dr), at(ridgeEnds[1], ridgeAt + tr / 2, ridgeTop)),
  };
  parts.push(ridgeBoard);
  // Ceiling joists beside the rafters between the gables.
  centres.slice(1, -1).forEach((centre, i) => {
    const a0 = centre + T / 2;
    parts.push({ id: `ceiling_joist_${i + 1}`, role: 'ceiling_joist', ...lumber(params.ceiling_joist), box: boxOf(at(a0, lo[b], zp), at(a0 + tj, hi[b], zp + dj)) });
  });

  // Gable studs on each gable wall's upper plate, cut to the rafters' underside.
  const byId = new Map(input.parts.map((/** @type {any} */ p) => [p.id, p]));
  const plateOf = (/** @type {string} */ id) => {
    const plate = byId.get(`${dep}/${id}`);
    if (!plate) throw new Error(`the storey's plate '${dep}/${id}' is not in the model`);
    return plate;
  };
  for (const gable of gableSides) {
    const boxes = lineOn(gable).plates.map((/** @type {string} */ id) => plateOf(id).world);
    const a0 = Math.min(...boxes.map((/** @type {any} */ x) => x.min[a])), a1 = Math.max(...boxes.map((/** @type {any} */ x) => x.max[a]));
    let k = 0;
    for (let c = lo[b] + params.spacing; c + ts / 2 <= hi[b] - ts; c += params.spacing) {
      const b0 = c - ts / 2, b1 = c + ts / 2;
      if (b0 < ridgeAt && b1 > ridgeAt) continue; // across the ridge line
      const side = b1 <= ridgeAt ? eavesSides[0] : eavesSides[1];
      const plane = undersides[side];
      const height = (/** @type {number} */ across) => { // the underside's height above `across`
        const p = plane.point, n = plane.normal;
        return p[2] - (n[b] * (across - p[b])) / n[2];
      };
      const low = Math.min(height(b0), height(b1)), high = Math.max(height(b0), height(b1));
      if (low - zp < MIN_GABLE_STUD) continue;
      k += 1;
      parts.push({
        id: `gable_stud_${gable}_${k}`, role: 'stud', ...lumber(params.gable_stud),
        box: boxOf(at(a0, b0, zp), at(a1, b1, high)),
        cuts: [{ normal: plane.normal, point: plane.point }],
      });
    }
  }

  // Joints, where parts touch.
  const plates = storey.lines.flatMap((/** @type {any} */ l) => l.plates.map((/** @type {string} */ id) => `${dep}/${id}`));
  const solids = core.solids;
  const near = (/** @type {any} */ x, /** @type {any} */ y) => [0, 1, 2].every(k => x.min[k] <= y.max[k] + 1 && y.min[k] <= x.max[k] + 1);
  const bounds = new Map(parts.map(p => [p.id, solids.isSolid(p) ? solids.boundingBox(p) : p.box]));
  const touches = (/** @type {any} */ p, /** @type {any} */ q, /** @type {any} */ qBox) => near(bounds.get(p.id), qBox) && solids.solidContact(p, q).normal !== null;
  /** @type {any[]} */
  const joints = [];
  const onPlate = { rafter: ['rafter_to_plate', 'rafter'], ceiling_joist: ['joist_to_plate', 'joist'], stud: ['stud_to_plate', 'stud'] };
  for (const p of parts) {
    const kind = /** @type {any} */ (onPlate)[p.role];
    if (!kind) continue;
    for (const id of plates) {
      const plate = byId.get(id);
      if (!touches(p, { box: plate.world }, plate.world)) continue;
      joints.push({ type: kind[0], parts: { plate: { model: id }, [kind[1]]: { own: p.id } } });
    }
  }
  const rafters = parts.filter(p => p.role === 'rafter');
  const others = parts.filter(p => ['ceiling_joist', 'stud', 'lookout'].includes(p.role));
  const pairType = { ceiling_joist: ['rafter_to_joist', 'joist'], stud: ['stud_to_rafter', 'stud'], lookout: ['lookout_to_rafter', 'lookout'] };
  for (const r of rafters) {
    if (!touches(r, ridgeBoard, ridgeBoard.box)) throw new Error(`'${r.id}' doesn't meet the ridge board`);
    joints.push({ type: 'rafter_to_ridge', parts: { ridge: { own: ridgeBoard.id }, rafter: { own: r.id } } });
    for (const o of others) {
      if (!touches(r, o, bounds.get(o.id))) continue;
      const [type, sideName] = /** @type {any} */ (pairType)[o.role];
      joints.push({ type, parts: { rafter: { own: r.id }, [sideName]: { own: o.id } } });
    }
  }
  for (const o of others) {
    if (o.role === 'stud' && !joints.some(j => j.type === 'stud_to_rafter' && j.parts.stud.own === o.id)) throw new Error(`'${o.id}' doesn't reach a rafter`);
  }
  return { parts, joints };
}

/** The box between two corners. */
function boxOf(/** @type {number[]} */ p, /** @type {number[]} */ q) {
  return { min: [0, 1, 2].map(i => Math.min(p[i], q[i])), max: [0, 1, 2].map(i => Math.max(p[i], q[i])) };
}

storey.code:
// Storey (derived): the walls on one level. Finds the wall lines (chains of
// wall_inline connections between wall_corner connections), runs wall_line
// for each, joins the lines' parts to what they lie on or against, and
// derives the floor under the walls (hut/design/ic_derived.md, sections 10
// and 11). Pure: no imports; the engine passes the library core.
//
// derive(params, input, core) -> {parts, joints}
//   input   entities: placed entities {id, module, variant, params, size,
//           transform, parts}; parts: every model part (world boxes in
//           `world`, layer if cut from one); connections: {id, interface,
//           ends: {role: {entity, port}}}; anchor: the anchor entity's id
//           (its frame is the building's); derive(id, params, input) runs a
//           derived child
//   result  own parts (ids prefixed by the child: line_S1/upper_plate_1,
//           floor/joist_1) and joints whose sides are {own: id} or {model: id};
//           exports, for the derived modules that come after (the roof), in
//           world coordinates, model +x east and +y north: outline (the
//           walls' framing in plan, {min: [x, y], max: [x, y]}), outside (the
//           walls with their sheets), plate_top (the upper top plates' top),
//           lines [{id, side: south | north | east | west, panels, plates}]
//           (plates: the line's upper plate pieces, own ids)
//
// The storey is derived only when the walls close: every line ends at a
// corner, four corners (wall_corner joins convex corners, so the walls make
// a rectangle).

/**
 * @param {object} params
 * @param {any} input
 * @param {any} core
 * @returns {{parts: any[], joints: any[], exports: any}}
 */
export function derive(params, input, core) {
  const entities = new Map(input.entities.map((/** @type {any} */ e) => [e.id, e]));
  const next = new Map(), prev = new Map(), corner = new Map();
  const walls = new Set();
  let corners = 0;
  for (const c of input.connections) {
    if (c.interface === 'wall_inline') {
      next.set(c.ends.a.entity, c.ends.b.entity);
      prev.set(c.ends.b.entity, c.ends.a.entity);
      walls.add(c.ends.a.entity); walls.add(c.ends.b.entity);
    } else if (c.interface === 'wall_corner') {
      const { through, butt } = c.ends;
      corner.set(`${through.entity}.${through.port}`, { role: 'through', other: butt.entity });
      corner.set(`${butt.entity}.${butt.port}`, { role: 'butt', other: through.entity });
      walls.add(through.entity); walls.add(butt.entity);
      corners += 1;
    }
  }

  // The wall lines; every end at a corner.
  const lines = [];
  const seen = new Set();
  const free = [];
  for (const id of [...walls].sort()) {
    if (prev.has(id)) continue;
    const line = [];
    for (let at = id; at !== undefined && !seen.has(at); at = next.get(at)) {
      seen.add(at);
      line.push(entities.get(at));
    }
    const first = line[0].id, last = line[line.length - 1].id;
    for (const key of [`${first}.left`, `${last}.right`]) if (!corner.has(key)) free.push(key);
    lines.push(line);
  }
  const looped = [...walls].filter(id => !seen.has(id));
  if (looped.length) throw new Error(`walls in a closed run with no corner: ${looped.join(', ')}`);
  if (free.length || corners !== 4) {
    throw new Error(`the walls don't close into a rectangle (free ends: ${free.join(', ') || 'none'}; `
      + `${corners} corners); the storey is derived once they do`);
  }

  const end = (/** @type {string} */ key) => {
    const c = corner.get(key);
    return { role: c.role, depth: entities.get(c.other).size.framing };
  };
  /** @type {any[]} */
  const parts = [];
  /** @type {any[]} */
  const joints = [];
  const prefix = (/** @type {string} */ p, /** @type {any} */ result) => {
    for (const part of result.parts) parts.push({ ...part, id: `${p}/${part.id}` });
    for (const j of result.joints) {
      joints.push({
        type: j.type,
        parts: Object.fromEntries(Object.entries(j.parts).map(([side, ref]) => [side,
          /** @type {any} */ (ref).own !== undefined ? { own: `${p}/${/** @type {any} */ (ref).own}` } : ref])),
      });
    }
  };
  for (const line of lines) {
    const first = line[0].id, last = line[line.length - 1].id;
    prefix(`line_${first}`, input.derive('wall_line', {}, {
      panels: line, ends: { start: end(`${first}.left`), end: end(`${last}.right`) },
    }));
  }

  // Join each upper plate piece to the top plates it lies on, the sheets
  // nailed to it, and, at a corner, the end of the plate it laps.
  const plates = parts.filter(p => p.role === 'top_plate');
  for (const own of plates) {
    for (const m of input.parts) {
      const c = core.contact(m.world, own.box);
      if (c.axis === null) continue;
      if (m.role === 'top_plate' && c.axis === 2 && m.world.max[2] === own.box.min[2]) {
        joints.push({ type: 'top_plates', parts: { upper: { own: own.id }, lower: { model: m.id } } });
      } else if (m.layer && c.axis !== 2 && core.nailable(m.world, own.box, c.axis)) {
        joints.push({ type: 'sheathing_to_framing', parts: { sheet: { model: m.id }, framing: { own: own.id } } });
      }
    }
  }
  const lineOf = (/** @type {string} */ id) => id.split('/')[0];
  for (let i = 0; i < plates.length; i++) {
    for (const other of plates.slice(i + 1)) {
      const a = plates[i];
      if (lineOf(a.id) === lineOf(other.id)) continue;
      const c = core.contact(a.box, other.box);
      if (c.axis === null) continue;
      // The plate whose end meets the other's side.
      const long = (/** @type {any} */ b) => (b.max[0] - b.min[0] > b.max[1] - b.min[1] ? 0 : 1);
      const [endPart, sidePart] = long(a.box) === c.axis ? [a, other] : [other, a];
      joints.push({ type: 'plate_end', parts: { end: { own: endPart.id }, side: { own: sidePart.id } } });
    }
  }

  const exports = summary(lines, plates, walls, entities);
  deriveFloor(input, core, walls, entities, parts, joints, prefix);
  return { parts, joints, exports };
}

/**
 * What the storey tells the derived modules after it: the outline, the
 * outside with the sheets, the upper top plates' top, and each wall line's
 * side (the way it faces) and upper plate pieces.
 * @param {any[][]} lines
 * @param {any[]} plates  the upper plate pieces (own ids, world boxes)
 * @param {Set<string>} walls
 * @param {Map<string, any>} entities
 */
function summary(lines, plates, walls, entities) {
  const wallParts = [...walls].flatMap(id => entities.get(id).parts);
  const extent = (/** @type {any[]} */ boxes) => ({
    min: [0, 1].map(i => Math.min(...boxes.map(b => b.min[i]))),
    max: [0, 1].map(i => Math.max(...boxes.map(b => b.max[i]))),
  });
  const outline = extent(wallParts.filter((/** @type {any} */ p) => p.role === 'bottom_plate').map((/** @type {any} */ p) => p.world));
  const outside = extent(wallParts.map((/** @type {any} */ p) => p.world));
  const mid = [0, 1].map(i => (outline.min[i] + outline.max[i]) / 2);
  return {
    outline,
    outside,
    plate_top: Math.max(...plates.map(p => p.box.max[2])),
    lines: lines.map(line => {
      const id = `line_${line[0].id}`;
      const own = plates.filter(p => p.id.startsWith(`${id}/`));
      const b = extent(own.map(p => p.box));
      const alongX = b.max[0] - b.min[0] >= b.max[1] - b.min[1];
      const centre = [0, 1].map(i => (b.min[i] + b.max[i]) / 2);
      const side = alongX ? (centre[1] < mid[1] ? 'south' : 'north') : (centre[0] < mid[0] ? 'west' : 'east');
      return { id, side, panels: line.map(e => e.id), plates: own.map(p => p.id) };
    }),
  };
}

const STANDING = new Set(['stud', 'king', 'jack', 'cripple']);

/**
 * The floor under the walls, laid out in the building's frame (the anchor
 * entity's), so it turns with the building: its outline is the extent of
 * the walls' bottom plates (their framing), its top their underside; the
 * joists span the short side, and the walls along the joists give the
 * members the blocking stands under (those over a rim stand on the rim).
 * @param {any} input
 * @param {any} core
 * @param {Set<string>} walls
 * @param {Map<string, any>} entities
 * @param {any[]} parts
 * @param {any[]} joints
 * @param {(p: string, r: any) => void} prefix
 */
function deriveFloor(input, core, walls, entities, parts, joints, prefix) {
  const placed = [...walls].map(id => entities.get(id));
  const frame = entities.get(input.anchor)?.transform;
  if (!frame) throw new Error('the floor needs the anchor entity placed');
  const back = core.invert(frame);
  const local = (/** @type {any} */ b) => core.applyBox(back, b);
  const plates = placed.flatMap(e => e.parts.filter((/** @type {any} */ p) => p.role === 'bottom_plate'));
  if (!plates.length) throw new Error('no bottom plates: the walls give the floor its outline');
  const boxes = plates.map((/** @type {any} */ p) => local(p.world));
  const lo = [0, 1, 2].map(i => Math.min(...boxes.map((/** @type {any} */ b) => b.min[i])));
  const hi = [0, 1].map(i => Math.max(...boxes.map((/** @type {any} */ b) => b.max[i])));
  // u along the rims, v along the joists: the joists span the short side.
  const [ua, va] = hi[1] - lo[1] <= hi[0] - lo[0] ? [0, 1] : [1, 0];
  const width = hi[ua] - lo[ua], depth = hi[va] - lo[va];
  const top = lo[2];
  const studs = new Set(placed.map(e => e.params.stud.id));
  if (studs.size !== 1) throw new Error(`the walls' stud lumber differs (${[...studs].join(', ')}); the sill needs one`);
  const sill = placed[0].params.stud;

  // The members standing on the bottom plates of the walls over each edge
  // along the joists (u = 0 and u = width), as [v0, v1].
  /** @type {{start: number[][], end: number[][]}} */
  const gables = { start: [], end: [] };
  for (const e of placed) {
    const own = e.parts.filter((/** @type {any} */ p) => p.role === 'bottom_plate').map((/** @type {any} */ p) => local(p.world));
    const runsAlongV = own.every((/** @type {any} */ b) => b.max[va] - b.min[va] >= b.max[ua] - b.min[ua]);
    if (!runsAlongV) continue;
    const u = (own[0].min[ua] + own[0].max[ua]) / 2 - lo[ua];
    const side = u < width / 2 ? 'start' : 'end';
    const base = Math.max(...own.map((/** @type {any} */ b) => b.max[2]));
    for (const p of e.parts) {
      const b = local(p.world);
      if (STANDING.has(p.role) && b.min[2] === base) gables[side].push([b.min[va] - lo[va], b.max[va] - lo[va]]);
    }
  }
  const toWorld = (/** @type {{min: number[], max: number[]}} */ b, /** @type {number} */ height) => {
    const map = (/** @type {number[]} */ c) => {
      const w = [0, 0, top - height + c[2]];
      w[ua] = lo[ua] + c[0];
      w[va] = lo[va] + c[1];
      return w;
    };
    return core.applyBox(frame, { min: map(b.min), max: map(b.max) });
  };
  prefix('floor', input.derive('floor', {}, { width, depth, sill, gables, toWorld }));
}

wall_line.code:
// Wall line (derived): the upper top plate along a straight run of wall
// panels, fitted on site (hut/design/ic_lib_top_plate.md). Pure: no imports;
// the engine passes the library core.
//
// derive(params, input, core) -> {parts, joints}
//   params  max_piece, min_from_joint (system file)
//   input   panels: the run's panels in order (left to right seen from
//           outside), each {id, size, params, transform, parts}, parts the
//           model's (world boxes in `world`); ends: {start, end}, each
//           {role: 'through' | 'butt', depth} at a corner (depth: the other
//           wall's framing depth) or null at a free end
//   result  parts in world coordinates; no joints (the storey joins the
//           plate to whatever it lies on or against)
//
// Along the run, s is the distance from the first panel's left end. The
// plate runs from the line's start to its end, extended by the through
// wall's framing at a butt end (to the outer corner) and stopped short by
// the butt wall's framing at a through end (at its inside face), so the
// plates lap at the corners. Its joints are at stud-grid positions (a
// panel's left end plus k times its spacing) at least min_from_joint from
// every panel joint and line end, over a stud or cripple that reaches the
// lower top plate; pieces at most
// max_piece, joints chosen greedily from the start.

const VERTICAL = new Set(['stud', 'cripple', 'king', 'jack']);

/**
 * @param {{max_piece: number, min_from_joint: number}} params
 * @param {{panels: any[], ends: {start: any, end: any}}} input
 * @returns {{parts: any[], joints: any[]}}
 */
export function derive(params, input) {
  const { panels, ends } = input;
  if (!panels.length) throw new Error('a wall line needs at least one panel');
  const first = panels[0];
  const dir = [0, 1, 2].map(i => first.transform.m[i][0]); // the run, left to right
  const axis = dir.findIndex(v => Math.abs(v) === 1);
  if (axis < 0 || axis === 2) throw new Error(`wall line at '${first.id}' doesn't run along x or y`);
  const origin = first.transform.t;
  const sOf = (/** @type {number[]} */ p) => (p[axis] - origin[axis]) * dir[axis];
  const span = (/** @type {{min: number[], max: number[]}} */ box) => {
    const a = sOf(box.min), b = sOf(box.max);
    return [Math.min(a, b), Math.max(a, b)];
  };

  // The panels' place along the run; they must be in line and face the same way.
  const runs = panels.map(panel => {
    const d = [0, 1, 2].map(i => panel.transform.m[i][0]);
    if (d.some((v, i) => v !== dir[i])) throw new Error(`panel '${panel.id}' doesn't run the same way as '${first.id}'`);
    const s0 = sOf(panel.transform.t);
    return { panel, s0, s1: s0 + panel.size.width };
  });
  const length = runs[runs.length - 1].s1;
  const boundaries = [...new Set(runs.flatMap(r => [r.s0, r.s1]))];

  // The lower top plate: the plate's section and lumber.
  const lower = first.parts.find((/** @type {any} */ p) => p.role === 'top_plate');
  if (!lower) throw new Error(`panel '${first.id}' has no top plate`);
  const thick = lower.world.max[2] - lower.world.min[2];

  const offset = (/** @type {any} */ end) => (end ? (end.role === 'butt' ? -end.depth : end.depth) : 0);
  const a = 0 + offset(ends.start);
  const b = length - offset(ends.end);

  // Joint positions.
  const candidates = [];
  for (const { panel, s0, s1 } of runs) {
    const spacing = panel.params.spacing;
    // Members that reach the lower top plate (not jacks or cripples under a
    // header or sill).
    /** @type {number[][]} */
    const members = panel.parts
      .filter((/** @type {any} */ p) => VERTICAL.has(p.role) && p.world.max[2] === lower.world.min[2])
      .map((/** @type {any} */ p) => span(p.world));
    for (let k = 1; s0 + k * spacing < s1; k++) {
      const c = s0 + k * spacing;
      if (boundaries.some(x => Math.abs(c - x) < params.min_from_joint)) continue;
      if (!members.some(([lo, hi]) => lo < c && c < hi)) continue;
      candidates.push(c);
    }
  }
  candidates.sort((p, q) => p - q);
  const pieces = [];
  let at = a;
  while (b - at > params.max_piece) {
    const next = candidates.filter(c => c > at && c <= at + params.max_piece && c < b).pop();
    if (next === undefined) {
      throw new Error(`no place for a joint in the upper top plate of the line from '${first.id}' `
        + `between ${at} and ${at + params.max_piece} along it (pieces at most ${params.max_piece}, `
        + `joints at least ${params.min_from_joint} from a panel joint, over a stud)`);
    }
    pieces.push([at, next]);
    at = next;
  }
  pieces.push([at, b]);

  const across = 1 - axis; // the other horizontal axis
  const parts = pieces.map(([s, e], index) => {
    const w0 = origin[axis] + dir[axis] * s, w1 = origin[axis] + dir[axis] * e;
    const min = [0, 0, 0], max = [0, 0, 0];
    min[axis] = Math.min(w0, w1); max[axis] = Math.max(w0, w1);
    min[across] = lower.world.min[across]; max[across] = lower.world.max[across];
    min[2] = lower.world.max[2]; max[2] = lower.world.max[2] + thick;
    return {
      id: `upper_plate_${index + 1}`, role: 'top_plate', material: lower.material, catalog: lower.catalog,
      stage: 'site', box: { min, max },
    };
  });
  return { parts, joints: [] };
}
